window.UNHL_RENDER_WEAPON = function(name, career, currentSeason, currentRank, seasonRow) {
  const safe = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const equipment = window.UNHL_WEAPONS[name];
  const photoPath = window.UNHL_WEAPON_PHOTOS[name];
  const photo = window.UNHL_EMBEDDED_STICKS[photoPath] || photoPath;
  const model = equipment ? equipment.model : 'WEAPON NOT YET IDENTIFIED';
  const brand = equipment ? equipment.brand : 'NOT IDENTIFIED';
  const stats = k => seasonRow && Number.isFinite(Number(seasonRow[k])) ? Number(seasonRow[k]) : '—';
  const rank = Number.isFinite(Number(currentRank)) && currentRank !== null ? '#'+currentRank : 'NR';
  const season = currentSeason || 'LATEST SEASON';
  const blue = /blue/i.test(model);
  return `<section class="loadout cinematic-armory" aria-label="${safe(name)} weapon of choice">
    <div class="cinematic-head">
      <div class="cinematic-head-top"><div class="cinematic-label">UNHL<br>PLAYER LOADOUT</div><div class="cinematic-tabs" role="tablist" aria-label="Player profile sections"><button type="button" class="selected" role="tab" aria-selected="true" data-loadout-tab="overview">OVERVIEW</button><button type="button" role="tab" aria-selected="false" data-loadout-tab="scoring">SCORING STATS</button><button type="button" role="tab" aria-selected="false" data-loadout-tab="winloss">WIN / LOSS</button></div></div>
      <div class="cinematic-identity"><h2>${safe(name)}</h2></div>
      <div class="cinematic-position">UNHL PLAYER <span class="cinematic-stripe"></span></div>
    </div>
    <div class="cinematic-overview" data-loadout-panel="overview">
    <div class="cinematic-weapon">
      <div class="cinematic-title"><span class="cinematic-target" aria-hidden="true">⊕</span><div><h3>WEAPON OF CHOICE</h3><p class="cinematic-stick-name">${safe(brand)} ${safe(model)}</p></div></div>
      <div class="cinematic-image-wrap ${photo?'has-photo':''}">${photo?`<img class="cinematic-stick" src="${photo}" alt="${safe(brand)} ${safe(model)} hockey stick" loading="eager">`:`<div class="cinematic-no-image">STICK IMAGE UNAVAILABLE</div>`}</div>
    </div>
    <div class="cinematic-stats"><div><span class="cinematic-stat-symbol">⊕</span><strong>${stats('g')}</strong><span>GOALS<small>${safe(season)} SEASON</small></span></div><div><span class="cinematic-stat-symbol">◇</span><strong>${stats('a')}</strong><span>ASSISTS<small>${safe(season)} SEASON</small></span></div><div><span class="cinematic-stat-symbol">☆</span><strong>${stats('pts')}</strong><span>POINTS<small>${safe(season)} SEASON</small></span></div><div><span class="cinematic-stat-symbol">▥</span><strong>${rank}</strong><span>SCORING RANK<small>${safe(season)} SEASON</small></span></div></div>
    <p class="cinematic-disclaimer">Season statistics and scoring rank are based on the latest available UNHL season. Equipment is the player's reported stick; goals and assists are not attributed to a particular stick.</p>
    </div>
    <div class="cinematic-tab-content" data-loadout-panel="scoring" hidden></div>
    <div class="cinematic-tab-content" data-loadout-panel="winloss" hidden></div>
  </section>`;
};
